using Microsoft.EntityFrameworkCore;

// EF Core 9 Cosmos DB breaking changes for existing documents:
// 1. Discriminator property renamed from "Discriminator" to "$type" — preserve old name
// 2. id property no longer contains discriminator — preserve old format
// 3. Sync I/O no longer supported — use async methods

class CosmosDbContext : DbContext
{
    public DbSet<Session> Sessions => Set<Session>();

    protected override void OnConfiguring(DbContextOptionsBuilder options)
    {
        options.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=...",
            "MyDatabase");
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Session>(b =>
        {
            b.ToContainer("Sessions");

            // Fix: Preserve "Discriminator" property name for existing documents
            // (EF Core 9 defaults to "$type")
            b.HasDiscriminator<string>("Discriminator");

            // Fix: Preserve old compound id format ("Session|<key>") for existing documents
            // (EF Core 9 defaults to key-only id)
            b.HasRootDiscriminatorInJsonId(true);
        });
    }
}

class Session
{
    public string Id { get; set; } = default!;
    public string Name { get; set; } = default!;
}

// Fix: Sync I/O (ToList, SaveChanges, etc.) now throws on Cosmos provider.
// All queries and saves must use async equivalents.
class CosmosQueryService
{
    private readonly CosmosDbContext _db;

    public CosmosQueryService(CosmosDbContext db) => _db = db;

    // BEFORE (breaks in EF Core 9):
    //   var sessions = _db.Sessions.Where(s => s.Name == name).ToList();
    //   _db.SaveChanges();

    // AFTER: use async methods
    public async Task<List<Session>> GetSessionsAsync(string name)
    {
        return await _db.Sessions.Where(s => s.Name == name).ToListAsync();
    }

    public async Task SaveAsync()
    {
        await _db.SaveChangesAsync();
    }
}

